def build_golden_set(output_path: str = "eval/golden_set.json"):
    os.makedirs(os.path.dirname(output_path), exist_ok=True)
    with open(output_path, "w", encoding="utf-8") as f:
        json.dump(GOLDEN_ITEMS, f, indent=2)
    print(f"Generated stratified golden set with {len(GOLDEN_ITEMS)} items at {output_path}")


if __name__ == "__main__":
    build_golden_set()
